\begin{tikzpicture}[x=1cm,y=1cm,every node/.style={font=\fontsize{10}{12}\selectfont},>=Stealth]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{hypotenuseRed}{HTML}{EF6068}
\coordinate (A) at (0,0);\coordinate (B) at (3,0);\coordinate (C) at (0,3);
\draw[black,line width=0.8pt] (A)--(B)--(C)--cycle;
\draw[black,line width=0.4pt] ($(A)!0.14!(B)$)--($(A)!0.14!(B)+(A)!0.14!(C)-(A)$)--($(A)!0.14!(C)$);
\pic[draw=black,line width=0.4pt,angle radius=6mm,angle eccentricity=1.5,"$\theta$"] {angle=C--B--A};
\path (C)--(B) node[midway,above,sloped,text=hypotenuseRed] {Hypotenuse};
\draw[hypotenuseRed,->,line width=0.8pt] ($(A)!0.12!(B)+(A)!0.12!(C)-(A)$)--($(C)!0.5!(B)$);
\end{tikzpicture}
[/tikz]

